/**
 * Merge overlapping intervals.
 *
 * Each interval is a two-element array [start, end] of finite numbers.
 * Malformed input (non-array, wrong length, or non-finite bounds) raises a
 * TypeError instead of silently producing a partial result.
 *
 * @param {Array<[number, number]>} list
 * @returns {Array<[number, number]>} merged intervals, sorted by start
 */
export function mergeIntervals(list) {
  if (list === null || list === undefined) return [];

  if (!Array.isArray(list)) {
    throw new TypeError("mergeIntervals: expected an array of intervals");
  }

  const normalized = list.map((interval, index) => {
    if (!Array.isArray(interval) || interval.length !== 2) {
      throw new TypeError(
        `mergeIntervals: interval at index ${index} is not a [start, end] pair`,
      );
    }
    const [start, end] = interval;
    if (
      typeof start !== "number" ||
      typeof end !== "number" ||
      !Number.isFinite(start) ||
      !Number.isFinite(end)
    ) {
      throw new TypeError(
        `mergeIntervals: interval at index ${index} has non-finite bounds`,
      );
    }
    return [start, end];
  });

  if (normalized.length === 0) return [];

  normalized.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const merged = [normalized[0]];
  for (let i = 1; i < normalized.length; i++) {
    const [start, end] = normalized[i];
    const last = merged[merged.length - 1];
    if (start <= last[1]) {
      // Overlap (including touching/adjacent intervals) → extend the current
      // merged interval to cover the union.
      if (end > last[1]) last[1] = end;
    } else {
      merged.push([start, end]);
    }
  }

  return merged;
}

