export function parseDuration(s) {
  if (typeof s !== "string") {
    throw new TypeError("parseDuration: expected a string, got " + typeof s);
  }
  if (s.length === 0) {
    throw new RangeError("parseDuration: empty string");
  }
  const match = /^(\d+)h(?:(\d+)m)?(?:(\d+)s)?$|^(\d+)m(?:(\d+)s)?$|^(\d+)s$/.exec(s);
  if (match === null) {
    throw new RangeError("parseDuration: invalid duration string: " + JSON.stringify(s));
  }
  const h = Number(match[1] ?? match[4] ?? 0);
  const m = Number(match[2] ?? match[5] ?? 0);
  const sec = Number(match[3] ?? match[6] ?? 0);
  return h * 3600 + m * 60 + sec;
}

