/**
 * Parse a compact duration string ("1h30m", "45s", "2h", "1h30m45s")
 * into a total number of seconds. Units: h, m, s.
 *
 * @param {string} s - Compact duration string.
 * @returns {number} Total seconds.
 * @throws {TypeError} When input is not a non-empty string or is malformed.
 */
export function parseDuration(s) {
  if (typeof s !== 'string' || s.length === 0) {
    throw new TypeError('parseDuration: expected a non-empty string');
  }

  // Each unit appears at most once, in h → m → s order, with integer amounts.
  const match = /^(\d+h)?(\d+m)?(\d+s)?$/.exec(s);
  if (!match) {
    throw new TypeError(`parseDuration: invalid duration "${s}"`);
  }

  const hours = match[1] ? Number(match[1].slice(0, -1)) : 0;
  const minutes = match[2] ? Number(match[2].slice(0, -1)) : 0;
  const seconds = match[3] ? Number(match[3].slice(0, -1)) : 0;

  return hours * 3600 + minutes * 60 + seconds;
}

export function parseRange(s) {
  if (typeof s !== 'string' || s.trim() === '') {
    throw new Error('invalid range input');
  }
  const out = [];
  for (const raw of s.split(',')) {
    const token = raw.replace(/\s+/g, '');
    if (token === '') {
      throw new Error('empty token');
    }
    const m = /^(\d+)(?:-(\d+))?$/.exec(token);
    if (!m) {
      throw new Error('malformed token: ' + token);
    }
    const a = Number(m[1]);
    if (m[2] === undefined) {
      out.push(a);
    } else {
      const b = Number(m[2]);
      if (a > b) {
        throw new Error('reversed range');
      }
      for (let i = a; i <= b; i++) {
        out.push(i);
      }
    }
  }
  return [...new Set(out)].sort((x, y) => x - y);
}

